<?php $money=static fn($n)=>number_format($n/100,2,',',' ');$weight=static fn($n)=>number_format($n/1000,3,',',' ');?>
<style>.sales-report h2{font-size:14px;color:#17643b;margin:18px 0 8px}.sales-report p{font-size:10px;line-height:1.5}.sales-report table{width:100%;border-collapse:collapse;table-layout:fixed;margin-bottom:16px}.sales-report th{background:#e9f3ec;color:#173c27;text-align:left}.sales-report th,.sales-report td{padding:7px 5px;border:1px solid #d6dfd9;font-size:9px;word-wrap:break-word;vertical-align:top}.sales-report thead{display:table-header-group}.sales-report tr{page-break-inside:avoid}.sales-report .num{text-align:right}.sales-report .note{color:#536458}.sales-report .cancelled{color:#9b3426}</style>
<div class="sales-report"><p><strong><?=e($report['scope'])?></strong><br>Édité le <?=e($report['issuedAt'])?> · <?=count($report['tickets'])?> ticket(s), toutes pages confondues.</p><p class="note">Tickets POS uniquement. Les ventes antérieures sans devise ne sont pas incluses. Les annulations sont exclues du chiffre d’affaires ; les devises restent séparées.</p>
<h2>Synthèse par devise</h2><table><thead><tr><th>Devise</th><th>Tickets encaissés</th><th>Chiffre d’affaires</th><th>Poids vendu (kg)</th><th>Tickets annulés</th><th>Montant annulé</th></tr></thead><tbody><?php foreach($report['summary']as$s):?><tr><td><?=e($s['currency'])?></td><td><?=$s['paid']?></td><td class="num"><?=$money($s['revenue_cents'])?></td><td class="num"><?=$weight($s['grams'])?></td><td><?=$s['cancelled']?></td><td class="num"><?=$money($s['cancelled_cents'])?></td></tr><?php endforeach;?></tbody></table>
<?php if(!$report['tickets']):?><p>Aucune vente pour ces filtres.</p><?php endif;?>
<h2>Ventes par article · tickets encaissés</h2><table><thead><tr><th>Article</th><th>Devise</th><th>Poids (kg)</th><th>Tickets</th><th>Montant vendu</th></tr></thead><tbody><?php foreach($report['articles']as$a):?><tr><td><?=e($a['name'])?></td><td><?=e($a['currency'])?></td><td class="num"><?=$weight($a['grams'])?></td><td><?=$a['count']?></td><td class="num"><?=$money($a['cents'])?></td></tr><?php endforeach;?></tbody></table>
<h2>Modes de paiement · tickets encaissés</h2><table><thead><tr><th>Devise</th><th>Paiement</th><th>Tickets</th><th>Montant vendu</th></tr></thead><tbody><?php foreach($report['payments']as$p):?><tr><td><?=e($p['currency'])?></td><td><?=e($p['method'])?></td><td><?=$p['count']?></td><td class="num"><?=$money($p['cents'])?></td></tr><?php endforeach;?></tbody></table>
<h2>Détail des tickets</h2><table><thead><tr><th style="width:21%">Ticket / date</th><th>Comptoir</th><th style="width:17%">Client / vendeur</th><th>Devise</th><th>Total</th><th>Paiement</th><th>Poids (kg)</th><th>État</th></tr></thead><tbody><?php foreach($report['tickets']as$t):?><tr><td><?=e($t['ticket_number'])?><br><?=e(date('d/m/Y H:i',strtotime($t['sold_at'])))?></td><td><?=e($t['counter_name'])?></td><td><?=e($t['customer_name'])?><br><?=e($t['cashier_name'])?></td><td><?=e($t['currency'])?></td><td class="num"><?=e(number_format((float)$t['total'],2,',',' '))?></td><td><?=e($report['methods'][$t['payment_method']])?></td><td class="num"><?=e(number_format((float)$t['quantity_kg'],3,',',' '))?></td><td class="<?=$t['status']==='cancelled'?'cancelled':''?>"><?=$t['status']==='paid'?'Encaissé':'Annulé'?></td></tr><?php endforeach;?></tbody></table></div>
